      <p v-if="notesError" class="error">{{ notesError }}</p><p v-if="notesLoading">Loading notes…</p><p v-else-if="!notes.length" class="empty">No relationship notes recorded.</p><div v-else class="relationship-notes"><article v-for="note in notes" :key="note.id" class="detail-card relationship-note"><header><h3>{{ formatDateTime(note.created_at) }} · {{ note.created_by_name || 'Unknown user' }}</h3><ActionMenu @edit="openNoteEdit(note)" @delete="pendingNoteDelete=note" /></header><pre>{{ note.body }}</pre><p v-if="note.next_step"><strong>Next step:</strong><br>{{ note.next_step }}</p><p v-if="note.follow_up_date"><strong>Follow-up:</strong> {{ note.follow_up_date }}</p><div class="note-attachments"><strong>Attachments</strong><ul v-if="note.attachments?.length"><li v-for="attachment in note.attachments" :key="attachment.id"><a :href="attachment.file" target="_blank" rel="noopener" :download="attachment.original_name">📎 {{ attachment.original_name }}</a><button v-if="canEdit" type="button" class="attachment-delete danger-text" aria-label="Remove attachment" @click="pendingAttachmentDelete=attachment">×</button></li></ul><span v-else class="muted">None</span><button v-if="canEdit" type="button" class="text-button" @click="openAttachmentPicker(note)">+ Add file</button></div></article></div>
      <div v-if="showNoteForm" class="modal-backdrop" @click.self="closeNoteForm"><form class="modal-card simple-form" @submit.prevent="saveNote"><div class="full-width modal-header"><div><h2>{{ editingNote ? 'Edit Note' : 'Add Relationship Note' }}</h2></div><button type="button" class="modal-close" @click="closeNoteForm">×</button></div><label class="full-width">Note<textarea v-model="noteForm.body" rows="5" required /></label><label class="full-width">Next step<textarea v-model="noteForm.next_step" rows="3" /></label><label>Follow-up date<input v-model="noteForm.follow_up_date" type="date"></label><label class="full-width">Attachments<input type="file" multiple @change="noteFiles=Array.from($event.target.files||[])"></label><ul v-if="noteFiles.length" class="selected-files full-width"><li v-for="file in noteFiles" :key="`${file.name}-${file.lastModified}`">{{ file.name }}</li></ul><p v-if="noteFormError" class="error full-width">{{ noteFormError }}</p><div class="modal-actions full-width"><button type="button" @click="closeNoteForm">Cancel</button><button class="primary" :disabled="noteSubmitting">{{ noteSubmitting?'Saving...':'Save note' }}</button></div></form></div>
      <input ref="attachmentInput" class="visually-hidden" type="file" multiple @change="uploadExistingAttachments">
