      <p v-if="mediaLoading">Loading photo reports…</p><p v-else-if="mediaError" class="error">{{ mediaError }}</p><p v-else-if="media.length === 0" class="empty">No photo reports recorded.</p><div v-else class="media-grid"><article v-for="item in media" :key="item.id" class="detail-card media-card"><div class="media-card-heading"><strong>{{ item.title }}</strong><ActionMenu @edit="openMediaEdit(item)" @delete="askDelete(item)" /></div><img :src="item.image" :alt="item.title"><p v-if="item.description">{{ item.description }}</p><small>{{ formatDate(item.uploaded_at) }} · <span>{{ item.is_public ? 'Public' : 'Private' }}</span></small></article></div>
      <ConfirmDialog :open="!!pendingDelete" :busy="mediaSubmitting" title="Delete photo report?" @cancel="pendingDelete=null" @confirm="deleteMedia" />
      <div v-if="mediaEdit" class="modal-backdrop"><form class="modal simple-form" @submit.prevent="saveMedia"><h2>Edit photo report</h2><label>Title<input v-model="mediaEdit.title" required></label><label>Description<textarea v-model="mediaEdit.description"></textarea></label><label class="checkbox"><input v-model="mediaEdit.is_public" type="checkbox"> Public</label><p v-if="mediaFormError" class="error">{{ mediaFormError }}</p><div class="modal-actions"><button type="button" @click="mediaEdit=null">Cancel</button><button class="primary" :disabled="mediaSubmitting">{{ mediaSubmitting?'Saving…':'Save' }}</button></div></form></div>
    </template>
  </div>
</template>
<script setup>
import { ref, computed, onMounted } from 'vue';import { useRoute } from 'vue-router';import client from '../api/client';import ActionMenu from '../components/ActionMenu.vue';import ConfirmDialog from '../components/ConfirmDialog.vue';import { ORGANIZATION_TYPE_LABELS, AGREEMENT_TYPE_LABELS, AGREEMENT_STATUS_LABELS } from '../constants/partnerships';const route=useRoute(),organization=ref(null),agreements=ref([]),media=ref([]),notes=ref([]),organizationLoading=ref(true),agreementsLoading=ref(true),mediaLoading=ref(true),notesLoading=ref(true),organizationError=ref(''),agreementsError=ref(''),mediaError=ref(''),notesError=ref(''),showAgreementForm=ref(false),showMediaForm=ref(false),agreementSubmitting=ref(false),mediaSubmitting=ref(false),agreementFormError=ref(''),mediaFormError=ref(''),agreementFieldErrors=ref({}),pendingDelete=ref(null),mediaEdit=ref(null),showNoteForm=ref(false),editingNote=ref(null),noteSubmitting=ref(false),noteFormError=ref(''),pendingNoteDelete=ref(null),noteDeleting=ref(false),noteDeleteError=ref(''),noteFiles=ref([]),attachmentInput=ref(null),attachmentTarget=ref(null),attachmentDeleting=ref(false),pendingAttachmentDelete=ref(null),attachmentError=ref('');const agreementTypeLabels=AGREEMENT_TYPE_LABELS,agreementStatusLabels=AGREEMENT_STATUS_LABELS,organizationType=computed(()=>ORGANIZATION_TYPE_LABELS[organization.value?.organization_type]||organization.value?.organization_type),canEdit=computed(()=>{const user=JSON.parse(localStorage.getItem('user')||'{}');return Boolean(user.is_superuser||user.is_staff||user.groups?.some(group=>['Partnership Editors'].includes(typeof group==='string'?group:group.name))) }),blankAgreement=()=>({title:'',agreement_type:'',status:'DRAFT',description:'',signed_date:'',start_date:'',expiration_date:''}),blankMedia=()=>({title:'',image:null,description:'',is_public:false}),blankNote=()=>({body:'',next_step:'',follow_up_date:''}),agreementForm=ref(blankAgreement()),mediaForm=ref(blankMedia()),noteForm=ref(blankNote());const formatDate=value=>value?new Date(value).toLocaleDateString():'—',formatDateTime=value=>value?new Date(value).toLocaleString():'—',list=data=>Array.isArray(data)?data:(data.results||[]),errorText=error=>error.response?.status===403?'You do not have permission to perform this action.':'Unable to save. Please review the form.';async function loadAgreements(){agreementsLoading.value=true;try{agreements.value=list((await client.get('/api/agreements/',{params:{organization:route.params.id}})).data);agreementsError.value=''}catch{agreementsError.value='Unable to load agreements.'}finally{agreementsLoading.value=false}}async function loadMedia(){mediaLoading.value=true;try{media.value=list((await client.get('/api/organization-media/',{params:{organization:route.params.id}})).data);mediaError.value=''}catch{mediaError.value='Unable to load photo reports.'}finally{mediaLoading.value=false}}async function loadNotes(){notesLoading.value=true;try{notes.value=list((await client.get('/api/organization-notes/',{params:{organization:route.params.id}})).data);await Promise.all(notes.value.map(async note=>{try{note.attachments=list((await client.get('/api/organization-note-attachments/',{params:{note:note.id}})).data)}catch{note.attachments=[]}}));notesError.value=''}catch{notesError.value='Unable to load relationship notes.'}finally{notesLoading.value=false}}function openNoteCreate(){editingNote.value=null;noteForm.value=blankNote();noteFiles.value=[];noteFormError.value='';showNoteForm.value=true}function openNoteEdit(note){editingNote.value=note;noteForm.value={body:note.body,next_step:note.next_step||'',follow_up_date:note.follow_up_date||''};noteFiles.value=[];noteFormError.value='';showNoteForm.value=true}function closeNoteForm(){if(noteSubmitting.value)return;showNoteForm.value=false;editingNote.value=null;noteForm.value=blankNote();noteFiles.value=[];noteFormError.value=''}async function uploadFiles(noteId,files){for(const file of files){const data=new FormData();data.append('note',noteId);data.append('file',file);await client.post('/api/organization-note-attachments/',data)}}async function saveNote(){if(noteSubmitting.value)return;noteSubmitting.value=true;noteFormError.value='';try{const payload={...noteForm.value,organization:Number(route.params.id),follow_up_date:noteForm.value.follow_up_date||null};let noteId;if(editingNote.value){noteId=editingNote.value.id;await client.patch(`/api/organization-notes/${noteId}/`,payload)}else{noteId=(await client.post('/api/organization-notes/',payload)).data.id}if(noteFiles.value.length)await uploadFiles(noteId,noteFiles.value);showNoteForm.value=false;editingNote.value=null;noteForm.value=blankNote();noteFiles.value=[];await loadNotes()}catch(error){noteFormError.value=errorText(error)}finally{noteSubmitting.value=false}}async function uploadExistingAttachments(){const files=Array.from(attachmentInput.value?.files||[]);if(!files.length||!attachmentTarget.value)return;attachmentError.value='';try{await uploadFiles(attachmentTarget.value.id,files);await refreshNoteAttachments(attachmentTarget.value);attachmentInput.value.value=''}catch(error){attachmentError.value=errorText(error)}finally{attachmentTarget.value=null}}async function refreshNoteAttachments(note){try{note.attachments=list((await client.get('/api/organization-note-attachments/',{params:{note:note.id}})).data)}catch(error){attachmentError.value=errorText(error)}}function openAttachmentPicker(note){attachmentTarget.value=note;attachmentError.value='';if(attachmentInput.value){attachmentInput.value.value='';attachmentInput.value.click()}}async function deleteAttachment(){if(!pendingAttachmentDelete.value||attachmentDeleting.value)return;attachmentDeleting.value=true;attachmentError.value='';try{const attachment=pendingAttachmentDelete.value;await client.delete(`/api/organization-note-attachments/${attachment.id}/`);pendingAttachmentDelete.value=null;const note=notes.value.find(item=>item.id===attachment.note);if(note)await refreshNoteAttachments(note)}catch(error){attachmentError.value=errorText(error)}finally{attachmentDeleting.value=false}}async function deleteNote(){if(!pendingNoteDelete.value||noteDeleting.value)return;noteDeleting.value=true;noteDeleteError.value='';try{await client.delete(`/api/organization-notes/${pendingNoteDelete.value.id}/`);pendingNoteDelete.value=null;await loadNotes()}catch(error){noteDeleteError.value=errorText(error)}finally{noteDeleting.value=false}}function resetAgreementForm(){agreementForm.value=blankAgreement();agreementFormError.value='';agreementFieldErrors.value={};showAgreementForm.value=false}function resetMediaForm(){mediaForm.value=blankMedia();mediaFormError.value='';showMediaForm.value=false}async function createAgreement(){if(agreementSubmitting.value)return;agreementSubmitting.value=true;agreementFormError.value='';agreementFieldErrors.value={};try{await client.post('/api/agreements/',{...agreementForm.value,organization:Number(route.params.id),signed_date:agreementForm.value.signed_date||null,start_date:agreementForm.value.start_date||null,expiration_date:agreementForm.value.expiration_date||null});resetAgreementForm();await loadAgreements()}catch(error){agreementFormError.value=error.response?.data&&typeof error.response.data==='object'&&error.response.status!==403?'':errorText(error);agreementFieldErrors.value=error.response?.status!==403&&error.response?.data&&typeof error.response.data==='object'?error.response.data:{}}finally{agreementSubmitting.value=false}}async function createMedia(){if(mediaSubmitting.value)return;mediaSubmitting.value=true;mediaFormError.value='';const data=new FormData();data.append('organization',route.params.id);data.append('title',mediaForm.value.title);data.append('image',mediaForm.value.image);data.append('description',mediaForm.value.description);data.append('is_public',mediaForm.value.is_public);try{await client.post('/api/organization-media/',data);resetMediaForm();await loadMedia()}catch(error){mediaFormError.value=errorText(error)}finally{mediaSubmitting.value=false}}function openMediaEdit(item){mediaFormError.value='';mediaEdit.value={id:item.id,title:item.title,description:item.description,is_public:item.is_public}}function askDelete(item){pendingDelete.value=item}async function saveMedia(){if(mediaSubmitting.value)return;mediaSubmitting.value=true;mediaFormError.value='';try{await client.patch(`/api/organization-media/${mediaEdit.value.id}/`,{title:mediaEdit.value.title,description:mediaEdit.value.description,is_public:mediaEdit.value.is_public});mediaEdit.value=null;await loadMedia()}catch(error){mediaFormError.value=errorText(error)}finally{mediaSubmitting.value=false}}async function deleteMedia(){if(!pendingDelete.value||mediaSubmitting.value)return;mediaSubmitting.value=true;mediaFormError.value='';try{await client.delete(`/api/organization-media/${pendingDelete.value.id}/`);pendingDelete.value=null;await loadMedia()}catch(error){mediaFormError.value=errorText(error)}finally{mediaSubmitting.value=false}}onMounted(async()=>{try{organization.value=(await client.get(`/api/organizations/${route.params.id}/`)).data}catch(error){organizationError.value=error.response?.status===404?'Organization not found.':'Unable to load organization.'}finally{organizationLoading.value=false};await Promise.all([loadAgreements(),loadMedia(),loadNotes()])})
